import { Injectable } from '@angular/core';
import { RawMaterial } from '../models/invoice';
import { HttpClient } from '@angular/common/http';
import { Observable } from 'rxjs';
import { environment } from '../environments/environments';
@Injectable({
  providedIn: 'root'
})
export class RawMaterialService {
   private apiUrl = `${environment.apiUrl}/RawMaterial`; 
  constructor(private http: HttpClient) {}

  getAllProducts(): Observable<RawMaterial[]> {
    return this.http.get<RawMaterial[]>(this.apiUrl);
  }
  getProductByID(id: number): Observable<RawMaterial> {
    return this.http.get<RawMaterial>(`${this.apiUrl}/${id}`)
  }
  addProduct(product: RawMaterial): Observable<RawMaterial> {
  return this.http.post<RawMaterial>(`${this.apiUrl}/create`, product);
}

updateProduct(id: number, product: RawMaterial): Observable<RawMaterial> {
  return this.http.put<RawMaterial>(`${this.apiUrl}/update/${id}`, product);
}

deleteProduct(id: number): Observable<void> {
  
  return this.http.delete<void>(`${this.apiUrl}/${id}`);
}
}
